from scipy.optimize import least_squares
def fit(tf, nt, fixmix=None):
    best=None
    rng=np.random.default_rng(7)
    for s in range(80):
        q0=np.r_[rng.uniform(0.05,2,nt), rng.uniform(0,4), rng.uniform(0,1)] if fixmix is None else rng.uniform(0.05,2,nt)
        def r(q):
            if fixmix is None:
                p,kk=q[nt],q[nt+1]
            else:
                p,kk=fixmix
            tb=tf(t,q[:nt])
            M=np.c_[tb, A**p*np.exp(-kk*t), A**2]
            c,*_=np.linalg.lstsq(M,y,rcond=None)
            return M@c-y
        try:
            rr=least_squares(r,q0,bounds=(np.r_[[-3.0]*nt]+([-1,-1] if fixmix is None else []),np.r_[[30]*nt]+([8,3] if fixmix is None else [])))
            if best is None or rr.cost<best.cost: best=(rr,rr.x)
        except Exception as e: pass
    rr,x=best
    return round(2*rr.cost/np.sum((y-y.mean())**2),9), np.round(x,5)
